    attribute rgbAccumulatorMs : Integer := 0;
    attribute rgbIndex : Integer := 0;
    perform action tick {
      first start;
      then assign led1AccumulatorMs := led1AccumulatorMs + io_10;
      then if led1AccumulatorMs >= 2000 {
